# ---- skin_wrinkle: carries age keywords on purpose (the age model uses them)
WR_LOC = S("on the forehead, around the eyes, around the mouth, across the cheeks, on the neck, along the jawline, between the brows, at the corners of the eyes, on the upper lip, under the eyes, on the chin, along the nose to the mouth")
WR_YOUNG = S("smooth firm skin, smooth taut skin, taut unlined skin, firm elastic skin, smooth plump skin, fresh unlined skin, smooth radiant skin, firm even skin")
WR_MID = S("faint expression lines, subtle fine lines, light laugh lines, gentle smile lines, soft faint lines, faint animated lines, slight creases when smiling")
WR_OLD = S("deep wrinkles, deeply etched lines, deeply creased skin, sagging skin, weather-etched wrinkles, papery crinkled skin, furrowed lines, aging creases, loose sagging skin folds, deep furrows, heavily lined skin, leathery creased skin")
def _wr(orig):
    out = [f'{w} {l}' for w in WR_YOUNG for l in WR_LOC]
    out += [f'{w} {l}' for w in WR_MID for l in WR_LOC]
    out += [f'{w} {l}' for w in WR_OLD for l in WR_LOC]
    out += [f'{w} {l}' for w in WR_OLD[:6] for l in WR_LOC[:6]]
    return sample(out, 300, 'skin_wrinkle') + WR_YOUNG + WR_MID + WR_OLD
R['skin_wrinkle'] = _wr

