reg('f_make_base', 'base makeup', [MK_STY, S("with a sheer foundation, with a full-coverage foundation, with a tinted moisturiser, with a skin tint, with a light concealer, with a powder set, with a setting spray, with a natural finish, with contour, with no contour, with a bare-skin look, with visible freckles showing through, with a satin finish, with a matte T-zone, with a luminous finish, with a blurred finish, with a balanced finish")], k=2, n=240, fmt='{a} {noun} {b}')
reg('f_make_blush', 'blush', [MK_STY, S("on the apples of the cheeks, swept along the cheekbones, high on the cheekbones, blended across the nose, on the cheeks and nose bridge, diffused across the cheeks, applied as a cream, applied as a powder, applied as a liquid tint, in a draped placement, in a sunburnt placement, in a subtle wash, in a defined stripe, with a sheer finish, with a shimmer finish")], k=2, n=240, fmt='{a} {noun} {b}')
reg('f_make_eyes', 'eye makeup', [MK_STY, S("with a defined winged liner, with a thin liner, with a smudged liner, with a bold graphic liner, with a soft smoky shadow, with a single wash of shadow, with a shimmer on the lid, with a matte neutral lid, with a cut crease, with soft blended shadow, with lashes curled and defined, with voluminous mascara, with natural-looking mascara, with lower-lash definition, with a waterline liner, with a bare eye, with glitter at the inner corner, with a halo effect, with tightlined lashes, with false lashes")], k=2, n=260, fmt='{a} {noun} {b}')
reg('f_make_hlite', 'highlighter', [MK_STY, S("on the cheekbones, on the brow bone, on the nose bridge, on the cupid's bow, on the inner corners of the eyes, on the collarbones, on the shoulders, along the temples, down the nose, on the high points of the face, as a soft glow, as a strobing effect, as a pearl wash, as a stripe, as a diffuse sheen")], k=2, n=220, fmt='{a} {noun} {b}')
reg('f_make_lips', 'lip makeup', [MK_STY, S("with a lip liner, with no liner, with a blurred edge, with a crisp edge, with a stain, with a balm, with a gloss, with a satin lipstick, with a matte lipstick, with a liquid lipstick, with an ombre effect, with a sheer wash, with a glitter topper, with a plumping gloss, with an overlined shape, with a natural shape, with a soft blotted look")], k=2, n=220, fmt='{a} {noun} {b}')
reg('f_eye_lash', 'eyelashes', [S("long, short, thick, sparse, curled, straight, natural, dense, fluttery, feathery, wispy, defined, separated, clumped, fine, bold, upswept, downward-pointing, full, delicate"),
    S("on the upper lids, on the upper and lower lids, with a curl, with no curl, with a doll-like flare, with a cat-eye flare, with a natural fan, with visible lash roots, with clean separation, with soft clumping, with a gentle tilt, with long outer corners, with short inner corners")], k=2, n=240, fmt='{a} {noun} {b}')
reg('m_eye_lash', 'eyelashes', [S("long, short, thick, sparse, curled, straight, natural, dense, fluttery, defined, separated, fine, full, delicate, subtle, strong, barely noticeable, soft, even, uneven, upswept, downward-pointing, feathery, wispy"),
    S("on the upper lids, on the upper and lower lids, with a gentle curl, with no curl, with a natural fan, with visible lash roots, with clean separation, with a soft tilt, with long outer corners, with short inner corners, with a slight clump, with fine tips, with a thick base, with a light curl at the tips, with a straight fall")], k=2, n=200, fmt='{a} {noun} {b}')
